xml.Script:
        W := 0.5;
        D  := W / 3;
        DCut := W;

        // angles of regular pyramid with three 85 degrees at the top
        Angle0 := 85 * Pi / 180;
        ca := cos(Angle0);
        Angle1 := arccos(sqrt((2 * ca + 1) / 3)); // bw Height and side edge
        Angle2 := arccos(ca / (ca + 1));          // bw sides

        // forming axes

        // Rotate p over v
        procedure RotatePoint(Xp, Yp, Zp, Xv, Yv, Zv, Angle, n);
        begin
          ca := Cos(Angle);
          sa := Sin(Angle);
          c2 := 1 - Cos(Angle);

          // make normalized vector
          da := sqrt(Xv^2 + Yv^2 + Zv^2);
          Xn := Xv / da;
          Yn := Yv / da;
          Zn := Zv / da;

          ax[n] := Xp * (Xn * c2 * Xn + ca) +
                   Yp * (Yn * c2 * Xn - sa * Zn) +
                   Zp * (Zn * c2 * Xn + sa * Yn);

          ay[n] := Xp * (Xn * c2 * Yn + sa * Zn) +
                   Yp * (Yn * c2 * Yn + ca) +
                   Zp * (Zn * c2 * Yn - sa * Xn);

          az[n] := Xp * (Xn * c2 * Zn - sa * Yn) +
                   Yp * (Yn * c2 * Zn + sa * Xn) +
                   Zp * (Zn * c2 * Zn + ca);
        end;

        RotatePoint(-1, 1,-1,  0, 1, 1, Angle1, 0);
        RotatePoint(-1, 1,-1,  1, 0,-1, Angle1, 3);
        RotatePoint(-1, 1,-1, -1,-1, 0, Angle1, 4);

        RotatePoint(ax[3], ay[3], az[3],  ax[4], ay[4], az[4],  Angle2, 1);
        RotatePoint(ax[4], ay[4], az[4],  ax[0], ay[0], az[0],  Angle2, 2);
        RotatePoint(ax[0], ay[0], az[0],  ax[3], ay[3], az[3],  Angle2, 5);

        // Calcs angle from 2 to 3 while rotating over 1

        function AngleI(i1, i2, i3);
        begin
            x1 := ay[i1] * az[i2] - ay[i2] * az[i1];
            y1 := az[i1] * ax[i2] - az[i2] * ax[i1];
            z1 := ax[i1] * ay[i2] - ax[i2] * ay[i1];
            x2 := ay[i1] * az[i3] - ay[i3] * az[i1];
            y2 := az[i1] * ax[i3] - az[i3] * ax[i1];
            z2 := ax[i1] * ay[i3] - ax[i3] * ay[i1];
            Result := ArcCos((x1*x2 + y1*y2 + z1*z2) / (x1^2 + y1^2 + z1^2));
        end;

        A1 := AngleI(0,3,4); // = Angle2
        A2 := AngleI(0,2,5);
        A3 := AngleI(1,2,5);
